// Modern approach: Outbox + Kafka (eventual consistency, resilient)
@Transactional
public void writeToDbAndOutbox() {
    orderRepo.save(order);
    outboxRepo.save(new OutboxEvent("order-events", order.getId(), payload));
    // Both in SAME DB TX. Relay publishes outbox to Kafka async.
}

// ─── @Modifying on @Query UPDATE/DELETE ───
public interface AccountRepository extends JpaRepository<Account, String> {

    // @Modifying REQUIRED for DML (UPDATE/DELETE) queries
    // Must run inside @Transactional
    @Modifying(clearAutomatically = true)  // clear persistence context after update
    @Query("UPDATE Account a SET a.status = 'FROZEN' WHERE a.balance < 0")
    int freezeNegativeBalances();

    // Without @Modifying: Spring thinks this is a SELECT → wrong behavior!
    // clearAutomatically=true: entities loaded BEFORE this query may be stale
    //   after the bulk update — clearing forces fresh reads
    // flushAutomatically=true: pending entity changes are flushed to DB
    //   before the query runs — ensures the query sees recent changes

    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("DELETE FROM Account a WHERE a.status = 'CLOSED' AND a.balance = 0")
    int purgeClosedAccounts();
}
